import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/column/Python-Programming-Course/P01-Programming-thinking/24-Little-ants-can-also-write-algorithms.html","title":"24-在没有光的地方，蚂蚁靠什么找到回家的路？","lang":"zh-CN","frontmatter":{"title":"24-在没有光的地方，蚂蚁靠什么找到回家的路？","icon":"read","date":"2025-04-23T19:39:42.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"feed":false,"seo":false,"head":[]},"git":{"createdTime":1669634625000,"updatedTime":1748754423000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":17,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":4}],"changelog":[{"hash":"ff4587c74d1c76d3aac787d3c96ea9dd9fecd743","time":1748754423000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更改文件夹名称"},{"hash":"871641c2877652b654f8565d255dea535a79ba90","time":1748751204000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"修改文件名称Python-Programming-Course"},{"hash":"3ff0b40d53c2817d14be1c56272bc16c65313bce","time":1745460756000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"update"},{"hash":"239d8e8425dd60bdd18f7428c792b2cc18636d88","time":1745460636000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"update"},{"hash":"c27396f6da6a58d1cedbffbd5ead79bfdc225f73","time":1745459749000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"完成图示"},{"hash":"4a98c68d911572e4d79b67fbd7bce101ba95f17b","time":1745417968000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Implement code changes to enhance functionality and improve performance"},{"hash":"40d28e48a5678b74e011d073a44569ec612c96f9","time":1745408984000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"完成"},{"hash":"8701a3cf29516c96fee406e979825acdc6aa9067","time":1745408418000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"新增文档《小蚂蚁也会写算法？》及相关信息"},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"aed1739bbe0401281f8fe9b23c9bcb44b448b9ac","time":1743333691000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"启用编辑链接，提升文档的可用性和用户体验"},{"hash":"f14b0cca174ae138ce78063f95445916775cebdb","time":1718679320000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"11"},{"hash":"e6ce4e085767c4f5b781fafab34fce9bb8a77757","time":1717922615000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"192.168.3.12"},{"hash":"698822ef18765f0a40a5fe8d17c8e37745f728e7","time":1717398270000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"2024-06-03 15:03:05"},{"hash":"772c411a931f42f9f56579305c16a96c1c834525","time":1675582584000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"e6a0f505dee0408ae039742ed8b7c873f3ccba3b","time":1675328574000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"添加 Python 教程"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"610fee0943c20fde9f54fa74b604beca191c1a25","time":1674624916000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"remove password"},{"hash":"f08aaa80880a7b22af128caca0dba27069f28dfa","time":1672843073000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"修复文章日期"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":8.18,"words":2455},"filePathRelative":"column/Python-Programming-Course/P01-Programming-thinking/24-Little-ants-can-also-write-algorithms.md"}`),a={name:`24-Little-ants-can-also-write-algorithms.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<h2 id="_1-自然界也会-写程序" tabindex="-1"><a class="header-anchor" href="#_1-自然界也会-写程序"><span>1. 自然界也会“写程序”？</span></a></h2><p>你可能一直以为，只有人类才能发明算法，毕竟电脑里的程序都是我们写的嘛！但今天，我们要揭开一个秘密——<strong>有些算法，其实是大自然“写”出来的</strong>！</p><p>别怀疑，大自然真的很懂“编程”。在它的“代码”里，藏着无数神奇的规律。很多生物，比如蜜蜂、蚂蚁、鸟群……它们的生活看似简单，其实背后都有一套套像程序一样的行为规则。为什么这么说呢？</p><p>还记得我前面给你提到的编程本质么？编程的本质其实就是让机器按照一定的规则，自己去做事情。在大自然里，很多生物都是<strong>严格按照自己的习性生活</strong>的。习性就相当于它们必须遵守的规则。所以，你完全可以把某些特定的生物看成是大自然编的“程序”。</p><p>而这些“自然程序”，启发了科学家们，创造出一系列<strong>超级厉害的人工智能算法</strong>。</p><p>比如：</p><ol><li>科学家从蜜蜂合作采蜜的过程中学到了<strong>蜂群算法</strong>；</li><li>从生物遗传进化的规则上学到了<strong>遗传算法</strong>。</li></ol><p>今天的主角，是一群你熟得不能再熟的小家伙——蚂蚁。</p><h2 id="_2-蚂蚁是怎么找吃的" tabindex="-1"><a class="header-anchor" href="#_2-蚂蚁是怎么找吃的"><span>2. 蚂蚁是怎么找吃的？</span></a></h2><p>蚂蚁是出了名的“团队高手”，一个蚁巢里通常住着几千、甚至几十万只蚂蚁。它们分工明确：</p><ul><li>有当妈妈的蚁后；</li><li>有保安兵蚁；</li><li>还有最辛苦的工蚁，负责找吃的。</li></ul><p>当工蚁出门觅食时，最开始的几只“侦察兵”会像探险家一样，满地乱跑，寻找目标。如果哪只幸运地发现了食物，它就会立刻回家报信。问题来了：它怎么告诉其他蚂蚁，食物在哪？</p><p>它们没有手机，不会发短信，甚至连手电筒都没有。但它们有个神技能——<strong>信息素</strong>！</p><p>每只蚂蚁在回家的路上都会撒下一种化学信号，也就是信息素。其他蚂蚁只要闻到这股味道，就能顺着这条“气味导航”找到食物。</p><p>当然了，发现这个食物的蚂蚁很可能不止一只。它们也会一边释放信息素，一边跑回巢穴去报告。但注意了，这些蚂蚁回巢穴的时候，走得并不一定是同一条路，而是你走你的，我走我的。</p><p>那咱们来<strong>假设</strong>一下：有一批蚂蚁侦查员，分头出去找食物。其中的一些蚂蚁找到了一大块食物，然后就各自跑回巢穴去报信。它们是各自回去报信的。然后，在报信的时候，它们刚好是沿着两条路返回的，<strong>一条路长一点，一条路短一点</strong>。那么现在问题来了，得到消息之后，蚁群大部队要去搬回食物的时候，会选哪一条路呢？</p><p>你可能会觉得，这还用问吗？当然是选短的了。但别忘了，蚂蚁没有地图，也没望远镜。接下来，我们就要探讨此问题。</p><h2 id="_3-哪条路更近-蚂蚁的-路线优化-大作战" tabindex="-1"><a class="header-anchor" href="#_3-哪条路更近-蚂蚁的-路线优化-大作战"><span>3. 哪条路更近？蚂蚁的“路线优化”大作战</span></a></h2><p>在开始之前，我们要说两个重要情况：</p><ul><li><strong>情况一</strong>：信息素是会慢慢挥发的。所以，一旦被释放出来，就会随着时间的推移，变得越来越淡。这么一来啊，为了不让这种路标消失，蚂蚁大部队里的每一只蚂蚁都会一边走，一边释放信息素；</li><li><strong>情况二</strong>：信息素越浓，蚂蚁越多。蚂蚁在寻找路线的时候，大概率会选择信息素浓度最高的路线。这个细节特别重要，是蚂蚁优化路线的关键所在；</li><li><strong>情况三</strong>：最开始的时候，这两条路上的<strong>信息素浓度</strong>和<strong>蚂蚁数量</strong>都差不多。我们假设，在1个小时的时间里，短一些的路上，蚂蚁能跑两个来回，而长一些的路上只能跑一个来回。这样一来，很明显，短一些的路线上信息素浓度，就会比长一些的高。</li></ul><p>我实际开始模拟一下：</p><figure><img src="/assets/raw-20250423221141424-CmdoVgnu.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>想象一下，有两条通往食物的路：一条近，一条远。一开始，蚂蚁并不知道哪条近，<s>它们就会随机走这两条路试试看。也就是</s>蚂蚁大军就又派出一些工蚁，<strong>兵分两路</strong>，试着走走看。</p><p>但神奇的事情发生了——<strong>走得快的蚂蚁会更频繁地往返（意味着：路程短，所以快），于是它们那条路上的信息素会积得更浓</strong>。而信息素越浓，吸引来的蚂蚁就越多。这样一来，越来越多的蚂蚁都会选择那条近路，最终几乎整个蚁群都会“进化”成走最短路线！</p><p>你看，没有地图和手机导航，靠大自然给定的规则，蚂蚁自己就选择了一条比较短的路线。</p><p>更厉害的是，蚂蚁不会一直墨守成规。<strong>只要给蚂蚁足够多的时间，它们还会进一步优化路线</strong>。这是因为，蚂蚁虽然大概率会沿着信息素浓度比较高的路线走，但这事儿并不绝对。</p><figure><img src="/assets/raw-CjVBzA5E.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>因为，有些有个性的蚂蚁非要<strong>开辟一条新的路线</strong>。如果这条路线比原来的路线长，那这条路上的信息素很快就消散掉了，这条路线也就被淘汰了。</p><p>但如果这条路线比原来的路线更短，蚂蚁来回一趟需要的时间也更短，那这条路线上的信息素浓度升高得会比较快。渐渐地，大部分蚂蚁又会走到这条路线上来，<strong>路线就被优化了</strong>。</p><p><s>如果碰巧这条新路更短，那它的信息素也会迅速增加，吸引更多蚂蚁前往。</s> 这种机制就像是在不断试错中寻找最优解——<strong>这，就是蚁群算法的核心思想</strong>。</p><h2 id="_4-人工智能的-电子蚂蚁-也上线了" tabindex="-1"><a class="header-anchor" href="#_4-人工智能的-电子蚂蚁-也上线了"><span>4. 人工智能的“电子蚂蚁”也上线了！</span></a></h2><figure><img src="/assets/raw-20250424094425483-4GcYjhCP.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>说到这，不知道你有没有发现，蚁群不断优化路线的思想对咱们的日常生活也特别有启发。——如果想找到新的更短的路径，就需要有蚂蚁去尝试新的路线。这就好比是，在一个群体里，需要有人能<strong>提出不同的意见</strong>。</p><p>所以，在做一件事情的时候，如果你想到了和别人不一样的办法，不用害怕，可以大胆地说出来讨论，说不定你的办法正是解决问题的最好办法呢。</p><p>蚂蚁觅食的过程可不光启发你的生活智慧，科学家也受到蚂蚁启发，对这个过程进行了总结。把这种找最优路径的方式搬进了计算机，发明了一种叫做“蚁群算法”的智能算法。蚁群算法在生活中的应用特别特别多。你最熟悉的，当然就是<strong>地图导航里的路线规划</strong>了。</p><p>用蚁群算法规划路线，几乎和蚂蚁找食物的过程一模一样。当然了，科学家肯定不能真的把蚂蚁塞进计算机里，否则可就有“bug”了，对吧。</p><p>不能塞真蚂蚁，那就用假蚂蚁。科学家们在计算机里设计了一种“<strong>电子蚂蚁</strong>”，告诉它们出发点和目的地，以及中间有哪些可能的道路。</p><p>之后，电子蚂蚁们就要开始运动了。和真蚂蚁一样，电子蚂蚁在运动的时候，也有两个重要的情况：</p><ul><li><strong>情况一</strong>：也会留下一种<strong>类似于信息素的信号</strong>（虚拟信息素）；</li><li><strong>情况二</strong>：在选择路径的时候，后来的电子蚂蚁也更<strong>倾向于选择信息素浓度比较高的路径</strong>。当然了，电子蚂蚁里面，也有一些喜欢冒险，开辟新路径的家伙。它们可能帮助蚁群找到更好的路径。（冒险的蚂蚁，可以类比成“随机”）</li></ul><p>而且，为了让电子蚂蚁能够更快地找到最短路线，科学家在大自然规则的基础上还做了一些改进，让蚂蚁之间可以高效率地交流信息。</p><h2 id="_5-用-类比思维-打开知识新大门" tabindex="-1"><a class="header-anchor" href="#_5-用-类比思维-打开知识新大门"><span>5. 用“类比思维”打开知识新大门</span></a></h2><figure><img src="/assets/raw-20250424095542203-BfQjNaK1.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>其实，像蚁群算法、蜂群算法、遗传算法……这些听起来很酷的人工智能技术，本质上都是从自然中“偷师学艺”来的。这种从熟悉事物中类推出新知识的方式，有个特别名字：<strong>类比思维</strong>。</p><p>我们小时候学数学，不就是从整数的加减法（四则运算），类比到小数和分数的计算吗？物理老师讲声波，也常常让我们想象水波荡漾的样子。这些，都是类比思维的具体运用。</p><p>类比思维的核心：<strong>用你熟悉的东西去类比陌生的东西</strong>，这对你理解和掌握知识特别有帮助。</p><p>下次你看到一只正在搬食物的蚂蚁，或许要对它肃然起敬。它身上可能正在运行一套比你手机 App 还先进的“自然算法”呢！</p>`,46)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};